def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = np.where(valid, rem, -np.inf)
    max_rem = np.max(valid_rem)
    almost_max_rem = np.max(np.where(valid_rem < max_rem, valid_rem, -np.inf))
    target_rem = almost_max_rem if almost_max_rem != -np.inf else max_rem
    return np.where(rem == target_rem, 0.0, np.where(valid, -abs(rem - target_rem), -np.inf))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = np.where(valid, rem, np.nan)
    median_rem = np.nanmedian(valid_rem)
    return np.where(valid, -np.abs(rem - median_rem), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, rem, -np.inf)
